    active_highest = 0.0
    for item in dangerous_prev:
        bid, obudget, ohp, onw = item
        pressure = bid
        if onw >= 1 or ohp <= 3:
            pressure += 4.0
        if obudget < 40:
            pressure -= 3.0
        if pressure > active_highest:
            active_highest = pressure

    survival_mode = hp <= 2 or no_water >= 2
